  2823	/**
  2824	 * @brief 跟车位移的核心：把地图中心移到 (lon,lat)。
  2825	 *
  2826	 * 未越 overscan 只平移画布；越界才 rebase（整幅重画）。拖动（pan_px）与
  2827	 * 跟车（set_center）共用这一条路径，避免两套几何。
  2828	 */
  2829	static void view_apply_center(vmap_view_t * view, double lon, double lat)
  2830	{
  2831	    double now_x = 0.0;
  2832	    double now_y = 0.0;
  2833	    double base_x = 0.0;
  2834	    double base_y = 0.0;
  2835	    double dx;
  2836	    double dy;
  2837	    double limit;
  2838	
  2839	    /*
  2840	     * 用**浮点** map 像素算位移（不能用整数版）：z14 下 1 map px = 1.69 screen px，
  2841	     * 先把中心量化到整数 map px 会把"拖动 200 px"变成 199 px（WP-VMAPAPI/R1 §4.1）。
  2842	     * 浮点位移直接交给 apply_canvas_pos，它只在上屏那一步取整、并把小数留在
  2843	     * `pan_rx` 里；重锚时再按整数部分滚动像素（见 render_begin）。
  2844	     */
  2845	    vmap_latlong_to_pixel_d(lat, lon, view->zoom, &now_x, &now_y);
  2846	    vmap_latlong_to_pixel_d(view->render_lat, view->render_lon, view->zoom,
  2847	        &base_x, &base_y);
  2848	
  2849	    dx = (now_x - base_x) * view->scale;
  2850	    dy = (now_y - base_y) * view->scale;
  2851	    view->lon = lon;
  2852	    view->lat = lat;
  2853	
  2854	    /*
  2855	     * Follow must not decode tiles. vmap_tile_cache_warm() is a blocking
  2856	     * LFS parse (~150ms) on this thread; doing it every GNSS tick once pan
  2857	     * crossed the old prefetch threshold pinned bicycle_ui at ~80% idle~10%.
  2858	     * New tiles load in vmap_view_render_pump() when the canvas rebases.
  2859	     */
  2860	    limit = (double)view->margin - (double)VMAP_PAN_GUARD;
  2861	
  2862	    /*
  2863	     * 航向朝上时，屏上看到的是**旋转后**的视口：它的四角离骑手是半对角线
  2864	     * r = hypot(view_w/2, view_h/2)（240x216 → 161 px），画布必须盖住它，否则
  2865	     * 45° 附近四角露底。骑手到画布边的余量 = margin + view_h/2 - |pan|，要求
  2866	     * 不小于 r ⇒ pan <= margin - (r - view_h/2) - guard。取较紧的竖向。
  2867	     */
  2868	    if (view->heading_up) {
  2869	        const double r = hypot((double)view->view_w / 2.0,
  2870	            (double)view->view_h / 2.0);
  2871	
  2872	        limit -= r - (double)view->view_h / 2.0;
  2873	        if (limit < 8.0) {
  2874	            limit = 8.0;
  2875	        }
  2876	    }
  2877	
  2878	    if (dx >= -limit && dx <= limit && dy >= -limit && dy <= limit) {
  2879	        bicycle_c_debug_map_soft_pan();
  2880	        vmap_view_apply_canvas_pos(view, dx, dy);
  2881	        vmap_follow_log(view, lon, lat);
  2882	        return;
  2883	    }
  2884	
  2885	    /* Soft-pan even when tiles cannot be reloaded (BLE LFS hold / in-flight pump). */
  2886	    if (view->pump_phase != 0 || myvendor_mtp_lfs_quiesce()) {
  2887	        bicycle_c_debug_map_soft_pan();
  2888	        vmap_view_apply_canvas_pos(view,
  2889	            vmap_clamp_d(dx, -limit, limit),
  2890	            vmap_clamp_d(dy, -limit, limit));
  2891	        vmap_follow_log(view, lon, lat);
  2892	        return;
  2893	    }
  2894	
  2895	    bicycle_c_debug_map_full_render();
  2896	    vmap_view_render(view);
  2897	}
