   112	static lv_coord_t helm_idle_glyph_w(const lv_font_t *font, uint32_t letter,
   113	                                   lv_coord_t min_w)
   114	{
   115	    lv_coord_t z;
   116	
   117	    z = (lv_coord_t)lv_font_get_glyph_width(font, letter, letter);
   118	    if (z < min_w) {
   119	        z = min_w;
   120	    }
   121	
   122	    return z;
   123	}
