   125	/**
   126	 * @brief 冒号相对数字的视觉中心差（px，正数 = 冒号偏低）。
   127	 * @details LVGL 按基线排字形：冒号只有下半截，直接排会偏下。按数字与冒号的
   128	 *          glyph ink 高/偏移算：dy = (h0 - hc)/2 + (ofs0 - ofsc)。
   129	 *          算不出来时返回 0（不偏移）。
   130	 */
   131	static lv_coord_t helm_idle_colon_dy(const lv_font_t *font)
   132	{
   133	    lv_font_glyph_dsc_t d0;
   134	    lv_font_glyph_dsc_t dc;
   135	
   136	    if (font == NULL
   137	        || !lv_font_get_glyph_dsc(font, &d0, (uint32_t)'0', 0)
   138	        || !lv_font_get_glyph_dsc(font, &dc, (uint32_t)':', 0)) {
   139	        return 0;
   140	    }
   141	
   142	    return (lv_coord_t)(((int32_t)d0.box_h - (int32_t)dc.box_h) / 2
   143	        + ((int32_t)d0.ofs_y - (int32_t)dc.ofs_y));
   144	}
