   146	/*
   147	 * 静止屏是**全屏黑白电子钟**：半透半反屏在背光关掉后靠环境光看，所以底用固定白、
   148	 * 字必须用**固定黑** —— 不能跟主题走。夜间调色板会把 INK 翻成浅色，配白底就是
   149	 * "白字白底"，日期/时间/「静止」三样全看不见（用户 2026-09-27 报的
   150	 * "静止状态的日期 时间 还有静止提示 都消失了"）。
   151	 */
   152	#define HELM_IDLE_INK   0x000000u
   153	
   154	static lv_obj_t *helm_idle_cell(lv_obj_t *row, const lv_font_t *font,
   155	                               lv_coord_t w, const char *txt)
   156	{
   157	    lv_obj_t *lab = helm_label(row, font, HELM_IDLE_INK, txt);
   158	
   159	    lv_obj_set_width(lab, w);
   160	    lv_label_set_long_mode(lab, LV_LABEL_LONG_MODE_CLIP);
   161	    lv_obj_set_style_text_align(lab, LV_TEXT_ALIGN_CENTER, 0);
   162	    return lab;
   163	}
