   165	static lv_obj_t *helm_idle_hms_build(lv_obj_t *parent, helm_idle_hms_t *out,
   166	                                    const lv_font_t *font, bool with_sec)
   167	{
   168	    lv_obj_t *row = lv_obj_create(parent);
   169	    lv_coord_t dw;
   170	    lv_coord_t cw;
   171	    lv_coord_t colon_dy;
   172	    uint8_t i;
   173	
   174	    dw = (lv_coord_t)(helm_idle_glyph_w(font, (uint32_t)'0', 10) + 2);
   175	    cw = (lv_coord_t)(helm_idle_glyph_w(font, (uint32_t)':', 8) + 4);
   176	    colon_dy = helm_idle_colon_dy(font);
   177	
   178	    lv_obj_remove_style_all(row);
   179	    lv_obj_set_size(row, LV_SIZE_CONTENT, LV_SIZE_CONTENT);
   180	    lv_obj_set_flex_flow(row, LV_FLEX_FLOW_ROW);
   181	    lv_obj_set_flex_align(row, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER,
   182	                          LV_FLEX_ALIGN_CENTER);
   183	    lv_obj_set_style_pad_column(row, 1, 0);
   184	    lv_obj_clear_flag(row, LV_OBJ_FLAG_SCROLLABLE);
   185	
   186	    out->ndigit = with_sec ? 6u : 4u;
   187	    for (i = 0; i < out->ndigit; i++) {
   188	        if (i == 2u || i == 4u) {
   189	            uint8_t ci = (i == 2u) ? 0u : 1u;
   190	
   191	            out->colon[ci] = helm_idle_cell(row, font, cw, ":");
   192	            lv_obj_set_style_translate_y(out->colon[ci], -colon_dy, 0);
   193	        }
   194	
   195	        out->d[i] = helm_idle_cell(row, font, dw, "0");
   196	    }
   197	
   198	    if (!with_sec) {
   199	        out->colon[1] = NULL;
   200	        out->d[4] = NULL;
   201	        out->d[5] = NULL;
   202	    }
